module Bytes = struct
  include Bytes
  external set_int8 : bytes -> int -> int -> unit = "%bytes_safe_set"
  let set_uint8 = set_int8
end
let () =
 let values = [min_int; -65537; -257; -256; -1; 0; 1; 127; 128; 255; 256; 257; 65535; max_int] in
 let writes = ref 0 in
 List.iter (fun value -> List.iter (fun index ->
  let b = Bytes.make 3 'U' in
  Bytes.set_uint8 b index value;
  for j = 0 to 2 do
   let expected = if j=index then value land 255 else 85 in
   if Char.code (Bytes.get b j) <> expected then failwith "written byte mismatch"
  done; incr writes
 ) [0;1;2]) values;
 List.iter (fun index ->
  let b = Bytes.make 3 'U' in
  let rejected = try Bytes.set_uint8 b index 42; false with Invalid_argument _ -> true in
  if not rejected then failwith "invalid index was accepted";
  if Bytes.to_string b <> "UUU" then failwith "invalid index changed buffer"
 ) [-1;3;max_int;min_int];
 let empty=Bytes.create 0 in
 let rejected=try Bytes.set_uint8 empty 0 42;false with Invalid_argument _->true in
 if not rejected || Bytes.length empty<>0 then failwith "empty buffer accepted";
 if !writes<>42 then failwith "incomplete valid cohort";
 print_endline "cases=47"

